import {readFileSync} from 'node:fs';
import {dirname,resolve,join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {Pool} from 'pg';
const root=resolve(dirname(fileURLToPath(import.meta.url)),'..');
const c=JSON.parse(readFileSync(join(root,'.private/postgres-18/connection.json'),'utf8'));
const admin=new Pool({host:c.host,port:c.port,user:c.adminUser,password:c.adminPassword,database:'postgres',max:1});
try {
 if(!(await admin.query('SELECT 1 FROM pg_roles WHERE rolname=$1',[c.appUser])).rowCount) {
  // Both names and hex password were generated by our fixed local bootstrap, not external input.
  if(c.appUser!=='pi_app_owner'||!/^[a-f0-9]{64}$/.test(c.appPassword))throw Error('invalid_local_bootstrap');
  await admin.query(`CREATE ROLE pi_app_owner LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE PASSWORD '${c.appPassword}'`);
 }
 if(!(await admin.query('SELECT 1 FROM pg_database WHERE datname=$1',[c.database])).rowCount) {
  if(c.database!=='pi_interview')throw Error('invalid_local_database');
  await admin.query('CREATE DATABASE pi_interview OWNER pi_app_owner');
 }
 console.log(JSON.stringify({status:'ready',database:c.database,app_role:c.appUser,superuser:false}));
}finally{await admin.end();}
